 * A CliError carries the exit code the process should use alongside the
 * single line that belongs on standard error.
 */
export class CliError extends Error {
  constructor(message, exitCode) {
    super(message)
    this.exitCode = exitCode
  }
}

export function usageError() {
  return new CliError('error: usage: cli.js waves|explain|pack <workers>', 2)
}

export function workersError() {
  return new CliError('error: workers must be a positive integer', 2)
}

export function lineError(message) {
  return new CliError(`error: ${message}`, 2)
}

export function unknownTaskError(name) {
  return new CliError(`error: unknown task ${name}`, 2)
}

export function cycleError(names) {
  return new CliError(`error: cycle: ${names.join(' -> ')}`, 3)
}
"}

