const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

/**
 * Split raw stdin text into the lines the spec wants: newline-separated,
 * with the empty tail a trailing newline leaves dropped.
 */
function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function checkName(name, line) {
  if (!NAME_PATTERN.test(name)) throw lineError(`line ${line}: invalid task name ${name}`)
}

/**
 * Parse the build graph text into a map of task name to { cost, deps }
 * where deps is a Set of dependency names, throwing a CliError for the
 * first problem the spec describes.
 */
export function parseGraph(text) {
  const lines = splitLines(text)
  const tasks = new Map()
  const depEntries = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw lineError(`line ${lineNumber}: expected task <name> <cost>`)
      const [, name, cost] = words
      checkName(name, lineNumber)
      if (!COST_PATTERN.test(cost)) throw lineError(`line ${lineNumber}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw lineError(`line ${lineNumber}: task ${name} is declared twice`)
      tasks.set(name, { cost: parseInt(cost, 10), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) throw lineError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      const name = words[1]
      const deps = words.slice(2)
      checkName(name, lineNumber)
      for (const dep of deps) checkName(dep, lineNumber)
      depEntries.push({ name, deps })
    } else {
      throw lineError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  for (const entry of depEntries) {
    if (!tasks.has(entry.name)) throw unknownTaskError(entry.name)
    for (const dep of entry.deps) {
      if (!tasks.has(dep)) throw unknownTaskError(dep)
    }
  }

  for (const entry of depEntries) {
    const task = tasks.get(entry.name)
    for (const dep of entry.deps) task.deps.add(dep)
  }

  return tasks
}
"}

