/**
 * Depth-first search the dependency graph for a cycle, visiting tasks and
 * each task's dependencies in ascending name order. Throws a CliError
 * describing the first cycle found, in the order the spec defines.
 */
function detectCycle(tasks) {
  const WHITE = 0
  const GRAY = 1
  const BLACK = 2
  const color = new Map()
  for (const name of tasks.keys()) color.set(name, WHITE)
  const stack = []

  function visit(name) {
    color.set(name, GRAY)
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const depColor = color.get(dep)
      if (depColor === GRAY) {
        const index = stack.indexOf(dep)
        throw cycleError([...stack.slice(index), dep])
      }
      if (depColor === WHITE) visit(dep)
    }
    color.set(name, BLACK)
    stack.pop()
  }

  for (const name of [...tasks.keys()].sort()) {
    if (color.get(name) === WHITE) visit(name)
  }
}

/**
 * Compute, for every task, its start time, finish time and wave depth. A
 * task's start is the greatest finish among its dependencies (0 when it
 * has none); its finish is its start plus its own cost; its depth is one
 * more than the greatest depth among its dependencies (0 when it has
 * none).
 */
function computeTimings(tasks) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const task = tasks.get(name)
    let s = 0
    let d = 0
    for (const dep of task.deps) {
      compute(dep)
      if (finish.get(dep) > s) s = finish.get(dep)
      if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
    }
    start.set(name, s)
    finish.set(name, s + task.cost)
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)
  return { start, finish, depth }
}

/**
 * Compute, for every task, the cost of the longest chain that starts at
 * it and runs down through its dependents to a task nothing depends on.
 */
function computePriorities(tasks) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, task] of tasks) {
    for (const dep of task.deps) dependents.get(dep).push(name)
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      const value = compute(dependent)
      if (value > best) best = value
    }
    const value = tasks.get(name).cost + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Analyze a parsed task map, throwing a cycle error if it isn't a DAG.
 * Returns the timings and priorities every command needs.
 */
export function analyzeGraph(tasks) {
  detectCycle(tasks)
  const { start, finish, depth } = computeTimings(tasks)
  const priority = computePriorities(tasks)
  let total = 0
  for (const value of finish.values()) if (value > total) total = value
  return { start, finish, depth, priority, total }
}

/**
 * Simulate the graph on a fixed number of workers, following the greedy
 * priority rule the spec describes.
 */
export function packWorkers(tasks, priority, workerCount) {
  const workers = Array.from({ length: workerCount }, () => ({ free: 0, log: [] }))
  const unscheduled = new Set(tasks.keys())
  const finishTime = new Map()

  let time = 0
  while (unscheduled.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      const readyNames = [...unscheduled].filter((name) => {
        for (const dep of tasks.get(name).deps) {
          const depFinish = finishTime.get(dep)
          if (depFinish === undefined || depFinish > time) return false
        }
        return true
      })

      let freeWorker = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].free <= time) {
          freeWorker = i
          break
        }
      }

      if (freeWorker === -1 || readyNames.length === 0) continue

      readyNames.sort((a, b) => {
        const diff = priority.get(b) - priority.get(a)
        return diff !== 0 ? diff : a < b ? -1 : a > b ? 1 : 0
      })
      const chosen = readyNames[0]
      const task = tasks.get(chosen)
      const start = time
      const end = start + task.cost
      workers[freeWorker].log.push({ name: chosen, start, finish: end })
      workers[freeWorker].free = end
      finishTime.set(chosen, end)
      unscheduled.delete(chosen)
      progressed = true
    }

    if (unscheduled.size === 0) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.free > time && worker.free < next) next = worker.free
    }
    time = next
  }

  let makespan = 0
  for (const value of finishTime.values()) if (value > makespan) makespan = value
  return { workers, makespan }
}
"}

