import { CliError, usageError, workersError } from './errors.js'
import { parseGraph } from './parse.js'
import { analyzeGraph, packWorkers } from './graph.js'

const WORKERS_PATTERN = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) throw workersError()
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw usageError()
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function formatWaves(tasks, depth, total) {
  const names = [...tasks.keys()].sort()
  let maxDepth = -1
  for (const value of depth.values()) if (value > maxDepth) maxDepth = value

  const byDepth = new Map()
  for (const name of names) {
    const d = depth.get(name)
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }

  const lines = []
  for (let d = 0; d <= maxDepth; d++) {
    lines.push(`wave ${d}: ${(byDepth.get(d) ?? []).join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(tasks, start, finish, depth, total) {
  const names = [...tasks.keys()].sort()
  const lines = names.map((name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(workers, makespan) {
  const lines = workers.map((worker, index) => {
    const entries = worker.log.map((entry) => ` ${entry.name}@${entry.start}-${entry.finish}`).join('')
    return `worker ${index}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const text = readStdin()
  const tasks = parseGraph(text)
  const { start, finish, depth, priority, total } = analyzeGraph(tasks)

  if (args.mode === 'waves') {
    process.stdout.write(formatWaves(tasks, depth, total))
  } else if (args.mode === 'explain') {
    process.stdout.write(formatExplain(tasks, start, finish, depth, total))
  } else {
    const { workers, makespan } = packWorkers(tasks, priority, args.workers)
    process.stdout.write(formatPack(workers, makespan))
  }
}

try {
  main()
} catch (error) {
  if (error instanceof CliError) {
    process.stderr.write(error.message + '\n')
    process.exit(error.exitCode)
  }
  throw error
}

